fn run_trusted_confirm_save(home: &Path, owner: &str, _instance: &str, payload: &Value) -> Result<Value, &'static str> {
    let operation_id = args_valid_id(payload, "operationId")?;
    agent_vitals_mcp::mcp::creator_session::confirm_task_save(home, payload, |context| {
        let artifact = &context["artifact"];
        let preview = &context["preview"];
        let preview_id = args_valid_id(preview, "previewId")?;
        let expected = args_u64(artifact, "expectedRevision")?;
        let committed = match artifact["kind"].as_str() {
            Some("creator-city") => {
                let actor = crate::creator_cities::city_preview_actor(preview_id);
                crate::creator_cities::commit_city(home, owner,
                    actor.as_deref().unwrap_or(crate::plugin_host::HEADLESS_CREATOR_INSTANCE),
                    args_valid_id(artifact, "cityId")?, preview_id, expected, operation_id)?
            }
            Some("creator-story") => crate::story_registry::commit_project_preview(home,
                args_valid_id(artifact, "storyId")?, preview_id, expected, operation_id, &preview["document"])?,
            Some("creator-project") => {
                let actor = scene_preview_actor(preview_id);
                commit_preview_as(home, owner, actor.as_deref().unwrap_or(crate::plugin_host::HEADLESS_CREATOR_INSTANCE),
                    args_valid_id(artifact, "projectId")?, preview_id, expected, operation_id)?
            }
            _ => return Err("creator_request_invalid"),
        };
        args_u64(&committed, "revision")
    }).map_err(|error| error.code)
}

/// pull 模式 submit 的服务端复核（creator_task_submit_result 经 broker 调用）：
/// 只读回答「preview 存在、绑定本 project、未过期」，不消费 preview。预览在创建时
/// 已过结构闸 + city-sdk 语义闸；baseRevision 与任务 artifact 的匹配由调用方比对。
fn run_task_preview_verify(_home: &Path, _owner: &str, _instance: &str, payload: &Value) -> Result<Value, &'static str> {
    let preview_id = args_valid_id(payload, "previewId")?;
    let mut previews = previews().lock().unwrap_or_else(|p| p.into_inner());
    previews.retain(|_, item| item.created.elapsed().is_ok_and(|age| age <= PREVIEW_TTL));
    let preview = previews.get(preview_id).ok_or("creator_preview_not_found")?;
    if let Some(project) = payload.get("projectId").and_then(Value::as_str) {
        if preview.project_id != project { return Err("creator_preview_project_mismatch"); }
    }
    Ok(json!({"previewId":preview_id,"projectId":preview.project_id,"baseRevision":preview.base_revision,
        "operationHash":preview.operation_hash}))
}

