    /// PR07 统一证据门禁：accept 拒绝宿主复算相左的证据（hostDisagreement）；直接
    /// 发布是强闸——只有 host-verified 且一致的候选证据能新建 Release，
    /// city-client-reported 只够本地接受、不够发布；门禁不挡候选/草稿持久化。
    #[test]
    fn evidence_gates_block_disagreement_and_require_host_verification_for_release() {
        let home = home();
        let (project_id, revision) = publishable_project(&home);
        let candidate = create_project_candidate(&home, &project_id, revision).unwrap();
        let candidate_id = candidate["candidateId"].as_str().unwrap().to_owned();
        // 宿主复算与客户端相左的落盘形态（host_annotate_evidence 的 disagreement 分支）。
        let disagreement = json!({"outcome":"success","snapshotDigest":candidate["contentDigest"],
            "evidenceSource":"city-client-reported","hostDisagreement":{"hostOutcome":"failure","hostCounters":{"next":1}}});
        let db = database(&home).unwrap();
        db.execute("INSERT INTO creator_playtest_runs(run_id,release_id,project_id,revision,studio_instance_id,status,active_slot,created_at_ms,expires_at_ms,finished_at_ms,evidence_json,return_consumed)
            VALUES('playtest-disagreement',?1,?2,?3,'studio-gate','completed',NULL,1,2,3,?4,1)",
            params![candidate_id.as_str(), project_id, revision, disagreement.to_string()]).unwrap();
        assert_eq!(accept_project_candidate(&home, &candidate_id).unwrap_err(), "creator_candidate_host_disagreement");
        assert_eq!(publish_project_release(&home, &project_id, revision).unwrap_err(), "creator_release_evidence_required");
        // 门禁不挡候选持久化：候选仍可幂等重建、照常读取。
        assert_eq!(create_project_candidate(&home, &project_id, revision).unwrap()["candidateId"].as_str(), Some(candidate_id.as_str()));
        // 一致但只是 client-reported：本地接受过闸（接受闸不变），不触发相左拒绝。
        let client_reported = json!({"outcome":"success","snapshotDigest":candidate["contentDigest"],"evidenceSource":"city-client-reported"});
        db.execute("UPDATE creator_playtest_runs SET evidence_json=?1 WHERE run_id='playtest-disagreement'", params![client_reported.to_string()]).unwrap();
        let accepted = accept_project_candidate(&home, &candidate_id).unwrap();
        assert_eq!(accepted["evidenceSource"], "city-client-reported");
        // 接受后该修订已有 Release：直接发布幂等返回同一条（不重过闸）。
        assert_eq!(publish_project_release(&home, &project_id, revision).unwrap()["releaseId"], accepted["releaseId"]);
        // 强闸只挡新建：新修订没有 host-verified 候选证据时直接发布必须拒绝。
        let skin_preview = preview_scene_operations(&home, "studio-instance", &project_id, revision,
            &json!([{"op":"skin.select","skinId":"desert-evening"}])).unwrap();
        commit_preview_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", &project_id,
            skin_preview["previewId"].as_str().unwrap(), revision, "gate-next-revision").unwrap();
        assert_eq!(publish_project_release(&home, &project_id, revision + 1).unwrap_err(), "creator_release_evidence_required");
        seed_host_verified_candidate(&home, &project_id, revision + 1);
        assert_eq!(publish_project_release(&home, &project_id, revision + 1).unwrap()["status"], "published");
        let _ = std::fs::remove_dir_all(home);
    }

    #[test]
    fn desktop_task_api_shares_the_creator_session_ledger() {
        let home = home();
        let session = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.session.open", &json!({"agentId":"studio-local","projectId":"project-shared","executor":"studio","transport":"studio-webview","capabilities":["studio.webview"]})).unwrap();
        let session_id = session["sessionId"].as_str().unwrap();
        // 桌面请求面必须和 Studio 的 request 名对上：list 读回会话档案，
        // update 写名称/草稿/首选执行器，未声明的键在 allowlist 层就被拒。
        let listed = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.session.list",
            &json!({"agentId":"studio-local","projectId":"project-shared"})).unwrap();
        assert_eq!(listed["sessions"][0]["sessionId"], json!(session_id));
        assert_eq!(listed["sessions"][0]["draft"], json!(""));
        dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.session.update",
            &json!({"agentId":"studio-local","sessionId":session_id,"label":"共享会话","draft":"检查车辆","preferredExecutor":"acp:claude"})).unwrap();
        let listed = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.session.list",
            &json!({"agentId":"studio-local","projectId":"project-shared"})).unwrap();
        assert_eq!(listed["sessions"][0]["label"], json!("共享会话"));
        assert_eq!(listed["sessions"][0]["draft"], json!("检查车辆"));
        assert_eq!(listed["sessions"][0]["preferredExecutor"], json!("acp:claude"));
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.session.update",
            &json!({"agentId":"studio-local","sessionId":session_id,"label":"x","unexpected":1})).unwrap_err(), "creator_request_invalid");
        let db = database(&home).unwrap();
        db.execute("INSERT INTO creator_projects(project_id,revision,document_json,created_at_ms,updated_at_ms) VALUES('project-shared',2,'{}',1,1)", []).unwrap();
        let created = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.task.create", &json!({"sessionId":session_id,"goal":"Shared task","humanRequest":"Review only",
            "artifact":{"kind":"creator-project","projectId":"project-shared","expectedRevision":2},
            "acceptanceCriteria":[{"criterionId":"manual","description":"Manual review","requiredEvidenceKind":"human-note"}],"operationId":"shared-goal"})).unwrap();
        let task_id = created["taskId"].as_str().unwrap();
        dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.task.plan.submit", &json!({"taskId":task_id,"expectedPlanRevision":1,"expectedArtifactRevision":2,
            "steps":[{"stepId":"review","title":"Review","kind":"review"}],"operationId":"shared-plan"})).unwrap();
        let approved = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.task.plan.approve", &json!({"taskId":task_id,"planRevision":1,"expectedArtifactRevision":2,"operationId":"shared-approve"})).unwrap();
        assert_eq!(approved["phase"], "ready");
        let cancelled = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.task.cancel", &json!({"taskId":task_id,"operationId":"shared-cancel"})).unwrap();
        assert_eq!(cancelled["phase"], "cancelled");
        let status = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio", "creator.session.status", &json!({"sessionId":session_id})).unwrap();
        assert!(status["jobs"].as_array().unwrap().iter().any(|job| job["kind"] == "studio-task" && job["status"] == "cancelled"));
        let events = dispatch_as(&home,LOCAL_CREATOR_OWNER,"studio","creator.events.subscribe",&json!({"taskId":task_id,"afterEventId":0,"limit":10,"timeoutMs":0})).unwrap();
        assert_eq!(events["events"].as_array().unwrap().len(),4);
        assert_eq!(events["events"][3]["kind"],"cancel");
        assert_eq!(events["waitTimedOut"],false);
        let capabilities = dispatch_as(&home,LOCAL_CREATOR_OWNER,"studio","creator.capabilities.status",&json!({})).unwrap();
        assert_eq!(capabilities["studioOnline"],true);
        dispatch_as(&home,LOCAL_CREATOR_OWNER,"studio","creator.connection.heartbeat",&json!({"agentId":"studio-local","sessionId":session_id,"state":"busy","lastStableError":null})).unwrap();
        let connections = dispatch_as(&home,LOCAL_CREATOR_OWNER,"studio","creator.connection.status",&json!({"agentId":"studio-local"})).unwrap();
        assert_eq!(connections["connections"][0]["state"],"busy");
        dispatch_as(&home,LOCAL_CREATOR_OWNER,"studio","creator.connection.disconnect",&json!({"agentId":"studio-local","sessionId":session_id})).unwrap();
        assert_eq!(dispatch_as(&home,LOCAL_CREATOR_OWNER,"studio","creator.events.subscribe",&json!({"taskId":task_id,"limit":0})).unwrap_err(),"invalid_argument");
        let _ = std::fs::remove_dir_all(home);
    }

    #[cfg(unix)]
    #[test]
    fn studio_acp_creates_city_story_and_game_revisions() {
        use agent_vitals_runtime::query::plugin_calls::{claim_pending, respond_with_budget};
        let home = home();
        let dispatch = |method: &str, payload: Value| dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-fixture", method, &payload);
        let game = create_project(&home, LOCAL_CREATOR_OWNER, "checkpoint-race", "create-game").unwrap();
        let project_id = game["projectId"].as_str().unwrap();
        let collider_project = create_project(&home, LOCAL_CREATOR_OWNER, "checkpoint-race", "create-collider-project").unwrap();
        let collider_project_id = collider_project["projectId"].as_str().unwrap();
        let mut game_rules = read_project(&home, project_id).unwrap()["game"].clone();
        game_rules["integerParameters"]["timeLimitTicks"]["default"] = json!(2400);
        let story_base = json!({"storyId":"fixture-story","title":"Story draft","schemaVersion":1,"storyVersion":"1.0.0",
            "graph":{"start":"start","nodes":[{"id":"start","kind":"beat"}],"edges":[]},"canon":{"characters":[]}});
        let story = crate::story_registry::project_create(&home, &story_base).unwrap();
        let mut story_document = story_base;
        story_document.as_object_mut().unwrap().remove("storyId");
        story_document["title"] = json!("Agent story");
        let profile = json!({"schemaVersion":1,"id":"arid-dunes","version":1,"biome":"arid",
            "geography":{"generator":"arid-dunes-v1","parameters":{"dunes":{"duneScale":190,"duneAmplitude":11,"orientationDeg":18}}},
            "visuals":{"themeId":"desert"}});
        let city = crate::creator_cities::create_city(&home, LOCAL_CREATOR_OWNER, "create-city", "City draft", 7, &profile).unwrap();
        let city_id = city["cityId"].as_str().unwrap();

        let agent_script = home.join("fixture-acp.py");
        std::fs::write(&agent_script, r#"
import json
import sys
proposal = json.loads(sys.argv[1])
expect_viewport = sys.argv[2] != "story"
restricted = False
for line in sys.stdin:
    request = json.loads(line)
    method = request["method"]
    if method == "initialize":
        result = {"protocolVersion": 1, "agentCapabilities": {"promptCapabilities": {"image": True}}, "authMethods": []}
    elif method == "session/new":
        assert request["params"]["mcpServers"][0]["name"] == "creator"
        result = {"sessionId": "fixture", "modes": {"currentModeId": "default", "availableModes": [{"id": "plan"}]}}
    elif method == "session/set_mode":
        restricted = request["params"]["modeId"] == "plan"
        result = {}
    elif method == "session/prompt":
        assert restricted
        images = [block for block in request["params"]["prompt"] if block["type"] == "image"]
        assert images == ([{"type":"image","mimeType":"image/jpeg","data":"AAAA"}] if expect_viewport else [])
        print(json.dumps({"jsonrpc":"2.0","method":"session/update","params":{"sessionId":"fixture",
            "update":{"sessionUpdate":"agent_message_chunk","content":{"type":"text","text":json.dumps(proposal)}}}}), flush=True)
        result = {"stopReason": "end_turn"}
    else:
        continue
    print(json.dumps({"jsonrpc":"2.0","id":request["id"],"result":result}), flush=True)
"#).unwrap();
        let cases = [
            ("city", city_id, json!({"kind":"creator-city","cityId":city_id,"expectedRevision":city["revision"]}),
                json!({"summary":"Adjust the coast","operations":[{"op":"world.set","params":{"shape.family":"lobed","shape.cores":3}}]}),
                "creator.city.edit.preview", "creator.city.read", json!({"cityId":city_id})),
            ("story", "fixture-story", json!({"kind":"creator-story","storyId":"fixture-story","expectedRevision":story["revision"]}),
                json!({"summary":"Rename the story","document":story_document}),
                "creator.story.project.preview", "creator.story.project.read", json!({"storyId":"fixture-story"})),
            ("game", project_id, json!({"kind":"creator-project","projectId":project_id,"expectedRevision":game["revision"]}),
                json!({"summary":"Adjust the race time limit","game":game_rules}),
                "creator.game.preview", "creator.project.read", json!({"projectId":project_id})),
            ("collider", collider_project_id, json!({"kind":"creator-project","projectId":collider_project_id,"expectedRevision":collider_project["revision"]}),
                json!({"summary":"Add a box obstacle","operations":[{"op":"scene.object.upsert","object":{
                    "id":"race-obstacle","kind":"collider","shape":"box","sizeMeters":{"x":4,"y":2,"z":3},
                    "transform":{"positionMeters":{"x":12,"y":1,"z":24},"rotationRadians":{"x":0,"y":0,"z":0},"scale":{"x":1,"y":1,"z":1}}}}]}),
                "creator.scene.preview", "creator.project.read", json!({"projectId":collider_project_id})),
        ];
        // Optional live smoke uses the same temporary artifacts and Host routes.
        let live_agent = std::env::var("OH_STUDIO_TEST_LIVE_ACP").ok();
        let registry: Value = serde_json::from_str(include_str!("../../plugins.json")).unwrap();
        let methods: Vec<String> = registry["plugins"].as_array().unwrap().iter()
            .find(|plugin| plugin["id"] == "creator-studio").unwrap()["localCalls"].as_array().unwrap()
            .iter().map(|method| method.as_str().unwrap().to_owned()).collect();
        let live_case = std::env::var("OH_STUDIO_TEST_LIVE_CASE").ok();
        if let Some(name) = live_case.as_deref() {
            assert!(live_agent.is_some() && cases.iter().any(|case| case.0 == name));
        }
        for (name, id, artifact, proposal, _preview_method, read_method, read_payload) in cases {
            if live_case.as_deref().is_some_and(|case| case != name) { continue; }
            let agent = match live_agent.as_deref() {
                Some(program) => json!({"id":"fixture","name":"Live ACP","command":program,"args":[]}),
                None => json!({"id":"fixture","name":"Fixture Agent","command":"python3",
                    "args":["-u",agent_script.to_str().unwrap(),proposal.to_string(),name]}),
            };
            std::fs::write(home.join("acp-agents.json"), json!({"agents":[agent]}).to_string()).unwrap();
            let revision = artifact["expectedRevision"].as_u64().unwrap();
            let session = dispatch("creator.session.open", json!({"agentId":"studio-fixture","projectId":id})).unwrap();
            let request = match name {
                "city" => "Set shape.family to lobed and shape.cores to 3.",
                "story" => "Change the story title to Agent story, preserving the graph and canon.",
                "collider" => "Add a 4×2×3 metre box collider at x=12, y=1, z=24.",
                _ => "Set the game integerParameters.timeLimitTicks.default to 2400, preserving everything else.",
            };
            let goal = if live_agent.is_some() {
                format!("{request} Return the proposal JSON directly, without confirmation or prose. This synthetic test expects this shape and values: {proposal}")
            } else { request.to_owned() };
            let created = dispatch("creator.task.create", json!({"sessionId":session["sessionId"],"goal":goal,
                "humanRequest":goal,"artifact":artifact,"operationId":format!("create:{name}"),
                "acceptanceCriteria":[{"criterionId":"agent-preview","description":"Host preview","requiredEvidenceKind":"preview"},
                    {"criterionId":"manual-review","description":"Confirm the saved revision","requiredEvidenceKind":"human-note"}]})).unwrap();
            let task_id = created["taskId"].as_str().unwrap();
            dispatch("creator.task.plan.submit", json!({"taskId":task_id,"expectedPlanRevision":1,"expectedArtifactRevision":revision,
                "steps":[{"stepId":"review","title":"Review","kind":"review"}],"operationId":format!("plan:{name}")})).unwrap();
            dispatch("creator.task.plan.approve", json!({"taskId":task_id,"planRevision":1,
                "expectedArtifactRevision":revision,"operationId":format!("approve:{name}")})).unwrap();

            let include_viewport = live_agent.is_none() && name != "story";
            let capture_method = if name == "city" { "creator.city.capture" } else { "creator.scene.capture" };
            let pending = std::thread::scope(|scope| {
                let worker = scope.spawn(|| dispatch("creator.task.execute", json!({"taskId":task_id,
                    "expectedPlanRevision":1,"expectedArtifactRevision":revision,"operationId":format!("execute:{name}"),
                    "mode":"restricted","executor":"acp:fixture","includeViewport":include_viewport,"timeoutMs":if live_agent.is_some() { 90_000 } else { 5_000 }})));
                while !worker.is_finished() {
                    let calls = claim_pending(&home, "creator-studio", "studio-fixture", &methods, 4).expect("Studio descriptor must be accepted by the mailbox");
                    for call in calls {
                        let method = call["method"].as_str().unwrap();
                        let mut payload = call["payload"].clone();
                        // Attach the semantic envelope as the Studio bridge would.
                        if method == "creator.game.preview" {
                            payload["validation"] = game_envelope(true, id, revision, &payload["game"]);
                        } else if method == "creator.scene.preview" {
                            payload = crate::plugin_host::headless_scene_preview_payload(&home, &payload).unwrap();
                        } else if method == "creator.city.edit.preview" {
                            payload = crate::plugin_host::headless_world_edit_payload(&home, &payload).unwrap();
                        }
                        let response = if method == capture_method {
                            assert!(include_viewport, "{name}: capture was not authorized for this task");
                            let id_key = if name == "city" { "cityId" } else { "projectId" };
                            assert_eq!(payload[id_key], id);
                            assert_eq!(payload["revision"], revision);
                            json!({"ok":true,"result":{(id_key):id,"revision":revision,"viewportRevision":revision,"isolatedViewport":true,
                                "dataUrl":"data:image/jpeg;base64,AAAA","width":1,"height":1,"bytes":3}})
                        } else {
                            match dispatch(method, payload) {
                                Ok(preview) => json!({"ok":true,"result":preview}),
                                Err(code) => json!({"ok":false,"error":{"code":code}}),
                            }
                        };
                        respond_with_budget(&home, "creator-studio", "studio-fixture",
                            call["callId"].as_str().unwrap(), &response, 512 * 1024).unwrap();
                    }
                    std::thread::sleep(std::time::Duration::from_millis(15));
                }
                worker.join().unwrap().unwrap_or_else(|code| panic!("{name} executor failed: {code}"))
            });
            assert_eq!(pending["phase"], "awaiting-review", "{name}");
            if name == "collider" {
                assert!(pending["evidence"].as_array().unwrap().iter().any(|evidence|
                    evidence["kind"] == "preview" && evidence["trustLevel"] == "host-observed"
                    && evidence["data"]["changedObjects"].as_array().is_some_and(|objects|
                        objects.iter().any(|object| object["id"] == "race-obstacle"))));
            }
            assert_eq!(dispatch(read_method, read_payload.clone()).unwrap()["revision"], revision);
            let confirm = json!({"taskId":task_id,"planRevision":1,"previewId":pending["proposedChangeSetId"],
                "expectedArtifactRevision":revision,"operationId":format!("confirm:{name}")});
            if name == "story" {
                let interrupted = agent_vitals_mcp::mcp::creator_session::confirm_task_save(&home, &confirm, |context| {
                    crate::story_registry::commit_project_preview(&home, id, context["preview"]["previewId"].as_str().unwrap(),
                        revision, "confirm:story", &context["preview"]["document"])?;
                    Err("creator_store_unavailable")
                }).unwrap_err();
                assert_eq!(interrupted.code, "creator_store_unavailable");
                assert_eq!(dispatch(read_method, read_payload.clone()).unwrap()["revision"], revision + 1);
                assert_eq!(dispatch("creator.task.status", json!({"taskId":task_id})).unwrap()["phase"], "awaiting-review");
            }
            let accepted = dispatch("creator.task.confirm_save", confirm.clone()).unwrap_or_else(|code| panic!("{name} confirm failed: {code}"));
            assert_eq!(accepted["phase"], "accepted", "{name}");
            assert_eq!(accepted["confirm"]["committedRevision"], revision + 1, "{name}");
            let replay = dispatch("creator.task.confirm_save", confirm).unwrap();
            assert_eq!(replay["confirm"]["recoveredFromReceipt"], true, "{name}");
            let saved = dispatch(read_method, read_payload).unwrap();
            assert_eq!(saved["revision"], revision + 1, "{name}");
            match name {
                "city" => assert_ne!(saved["profile"], profile),
                "story" => assert_eq!(saved["title"], "Agent story"),
                "game" => assert_eq!(saved["game"]["integerParameters"]["timeLimitTicks"]["default"], 2400),
                "collider" => assert_eq!(saved["scene"]["objects"][0]["sizeMeters"], json!({"x":4,"y":2,"z":3})),
                _ => unreachable!(),
            }
        }
        std::fs::remove_dir_all(home).unwrap();
    }

    #[test]
    fn city_layout_catalog_is_revision_bound_and_projects_can_pin_it() {
        let home = home();
        let snapshot = layout_snapshot();
        assert_eq!(publish_city_layout_snapshot(&home, &snapshot).unwrap()["worldRevision"], "world-rev-test");
        assert_eq!(publish_city_layout_snapshot(&home, &snapshot).unwrap()["anchorCount"], 4);
        let mut changed = snapshot.clone(); changed["seed"] = json!(8);
        assert_eq!(publish_city_layout_snapshot(&home, &changed).unwrap_err(), "creator_layout_revision_conflict");
        let layouts = list_city_layout_snapshots(&home, 8).unwrap();
        assert_eq!(layouts["layouts"][0]["anchorCount"], 4);
        let project = create_project_from_city_layout(&home, LOCAL_CREATOR_OWNER, "checkpoint-race", "create-bound", "world-rev-test").unwrap();
        let saved = read_project(&home, project["projectId"].as_str().unwrap()).unwrap();
        assert_eq!(saved["cityLayout"]["worldRevision"], "world-rev-test");
        assert_eq!(saved["cityLayout"]["layout"]["id"], "city-layout-v1-test");
        let _ = std::fs::remove_dir_all(home);
    }

    #[test]
    fn creator_mount_rejects_anchors_disconnected_in_the_pinned_city_topology() {
        let home = home();
        let mut snapshot = layout_snapshot();
        snapshot["worldRevision"] = json!("world-rev-disconnected");
        snapshot["layout"]["links"].as_array_mut().unwrap().pop();
        publish_city_layout_snapshot(&home, &snapshot).unwrap();
        let created = create_project_from_city_layout(&home, LOCAL_CREATOR_OWNER, "checkpoint-race", "create-disconnected", "world-rev-disconnected").unwrap();
        let project_id = created["projectId"].as_str().unwrap();
        let project = read_project(&home, project_id).unwrap();
        let game_digest = digest(&canonical_json(&project["game"]).unwrap());
        let mount = json!({
            "schemaVersion":1,"mountId":"disconnected-mount",
            "layout":{"kind":"city-layout","id":"city-layout-v1-test","version":"1","digest":"world-rev-disconnected"},
            "game":{"kind":"city-minigame","id":project["game"]["id"],"version":"1","digest":game_digest},
            "entryAnchorId":"road-spawn:a","bindings":{"points":["road-checkpoint:ab","road-checkpoint:bc","road-checkpoint:cd"]},"parameterOverrides":{"timeLimitTicks":2400}
        });
        // 语义搬运（§7 P2）：可达性归 city-sdk（信封判负）。Rust 结构侧接受
        // 形状合法的挂载并签发 preview，commit 闸门以 creator_preview_invalid 拒绝。
        let bind_ops = json!([{"op":"mount.bind","mount":mount}]);
        let rejected = preview_scene_operations_validated(&home, "studio-instance", project_id, 0,
            &bind_ops, Some(&scene_envelope(false, project_id, 0, &bind_ops))).unwrap();
        assert_eq!(commit_preview_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", project_id,
            rejected["previewId"].as_str().unwrap(), 0, "commit-disconnected").unwrap_err(), "creator_preview_invalid");
        assert_eq!(read_project(&home, project_id).unwrap()["revision"], 0);
        let _ = std::fs::remove_dir_all(home);
    }

    #[test]
    fn city_release_is_immutable_revision_bound_and_filtered_by_current_layout() {
        let home = home();
        let (project_id, revision) = publishable_project(&home);
        assert_eq!(revision, 1);
        assert!(list_city_releases(&home, "city-layout-v1-test", "world-rev-test", 8).unwrap()["releases"].as_array().unwrap().is_empty());
        assert_eq!(publish_project_release(&home, &project_id, 0).unwrap_err(), "revision_conflict");

        seed_host_verified_candidate(&home, &project_id, revision);
        let first = publish_project_release(&home, &project_id, revision).unwrap();
        let first_id = first["releaseId"].as_str().unwrap().to_owned();
        assert_eq!(publish_project_release(&home, &project_id, revision).unwrap(), first);
        let first_read = dispatch_city_runtime(&home, "city-instance", "city.creator.experiences.read", &json!({
            "releaseId":first_id,"layoutId":"city-layout-v1-test","worldRevision":"world-rev-test"
        })).unwrap();
        assert_eq!(first_read["revision"], 1);
        assert_eq!(first_read["skinId"], "miami-vice");
        assert_eq!(first_read["mounts"][0]["mountId"], "release-mount");
        assert_eq!(first_read["scene"]["objects"], json!([]));
        assert_eq!(first_read["assets"]["entries"], json!([]));
        assert_eq!(first_read["assetRefs"], json!([]));

        let mut second_layout = layout_snapshot();
        second_layout["worldRevision"] = json!("world-rev-other");
        second_layout["layout"]["id"] = json!("city-layout-v1-other");
        publish_city_layout_snapshot(&home, &second_layout).unwrap();
        assert!(list_city_releases(&home, "city-layout-v1-other", "world-rev-other", 8).unwrap()["releases"].as_array().unwrap().is_empty());
        assert_eq!(read_city_release(&home, &first_id, "city-layout-v1-other", "world-rev-other").unwrap_err(), "creator_release_not_found");
        assert_eq!(dispatch_city_runtime(&home, "city-instance", "city.creator.experiences.list", &json!({
            "layoutId":"city-layout-v1-test","worldRevision":"world-rev-test","limit":8,"includeDrafts":true
        })).unwrap_err(), "creator_method_unavailable");

        let saved = read_project(&home, &project_id).unwrap();
        let skin_preview = preview_scene_operations(&home, "studio-instance-2", &project_id, revision,
            &json!([{"op":"skin.select","skinId":"desert-evening"}])).unwrap();
        commit_preview_as(&home, LOCAL_CREATOR_OWNER, "studio-instance-2", &project_id,
            skin_preview["previewId"].as_str().unwrap(), revision, "revise-after-release").unwrap();
        seed_host_verified_candidate(&home, &project_id, revision + 1);
        let second = publish_project_release(&home, &project_id, revision + 1).unwrap();
        assert_ne!(second["releaseId"], first["releaseId"]);
        let second_read = read_city_release(&home, second["releaseId"].as_str().unwrap(), "city-layout-v1-test", "world-rev-test").unwrap();
        assert_eq!(second_read["skinId"], "desert-evening");
        assert_eq!(read_city_release(&home, &first_id, "city-layout-v1-test", "world-rev-test").unwrap(), first_read);
        assert_eq!(publish_project_release(&home, &project_id, revision).unwrap_err(), "revision_conflict");
        assert_eq!(saved["revision"], revision);
        let _ = std::fs::remove_dir_all(home);
    }

    // MCP 试玩闭环（设计 §6.3）：归属校验拒绝 → pending 取消 → result 终态 →
    // 重复取消幂等；claimed 取消同样收敛；未知 runId 明确 not_found。
    #[test]
    fn playtest_start_result_cancel_reach_unique_terminal_states() {
        let home = home();
        let (project_id, revision) = publishable_project(&home);
        seed_host_verified_candidate(&home, &project_id, revision);
        let published = publish_project_release(&home, &project_id, revision).unwrap();
        let release_id = published["releaseId"].as_str().unwrap().to_owned();
        // 归属不符直接拒绝，且不产生 run
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start",
            &json!({"releaseId":release_id,"projectId":"other-project","expectedRevision":revision})).unwrap_err(), "creator_release_project_mismatch");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start",
            &json!({"releaseId":release_id,"expectedRevision":revision + 1})).unwrap_err(), "creator_release_revision_mismatch");
        // 契约形状启动：requestId 透传，结果带 project/revision
        let start = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start",
            &json!({"releaseId":release_id,"projectId":project_id,"expectedRevision":revision,"requestId":"mcp-req-1"})).unwrap();
        assert_eq!(start["projectId"], project_id);
        assert_eq!(start["revision"], revision);
        assert_eq!(start["requestId"], "mcp-req-1");
        let run_id = start["runId"].as_str().unwrap().to_owned();
        // pending → result
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.result", &json!({"runId":run_id})).unwrap()["status"], "pending");
        // claim 后取消：City 的 finish 收到干净终态拒绝
        assert_eq!(dispatch_city_runtime(&home, "city-instance", "city.creator.playtest.claim", &json!({})).unwrap()["runId"], run_id);
        let cancelled = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.cancel", &json!({"runId":run_id})).unwrap();
        assert_eq!(cancelled["status"], "cancelled");
        assert_eq!(cancelled["cancelled"], true);
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.result", &json!({"runId":run_id})).unwrap()["status"], "cancelled");
        // 重复取消幂等：返回原终态，不再变更
        let again = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.cancel", &json!({"runId":run_id})).unwrap();
        assert_eq!(again, json!({"runId":run_id,"projectId":project_id,"revision":revision,"status":"cancelled","cancelled":false}));
        // 取消后活动槽位释放：可以启动新 run
        let second = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start", &json!({"releaseId":release_id})).unwrap();
        assert_ne!(second["runId"], run_id);
        // 未知 runId
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.result", &json!({"runId":"playtest-missing"})).unwrap_err(), "creator_playtest_not_found");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.cancel", &json!({"runId":"playtest-missing"})).unwrap_err(), "creator_playtest_not_found");
        let _ = std::fs::remove_dir_all(home);
    }

    // MCP P0（设计 §6.4）：场景摘要 + 能力发现 + 预览结构化差异。
    #[test]
    fn scene_describe_capabilities_and_preview_diff_are_bounded() {
        let home = home();
        publish_city_layout_snapshot(&home, &layout_snapshot()).unwrap();
        let created = create_project_from_city_layout(&home, LOCAL_CREATOR_OWNER, "checkpoint-race", "create-describe", "world-rev-test").unwrap();
        let project_id = created["projectId"].as_str().unwrap().to_owned();
        // 一个锚点对象让类别计数非零；预览结果必须带结构化差异
        let preview = preview_scene_operations(&home, "studio-instance", &project_id, 0, &json!([
            {"op":"anchor.upsert","object":{"id":"zone:gazebo","kind":"anchor","anchor":{"id":"zone:gazebo","kind":"zone","capabilities":["drive"],"geometryRef":"preview-node:z"},"transform":{"positionMeters":{"x":1.0,"y":0.0,"z":2.0},"rotationRadians":{"x":0.0,"y":0.0,"z":0.0},"scale":{"x":1.0,"y":1.0,"z":1.0}}}}
        ])).unwrap();
        assert_eq!(preview["changedObjects"][0]["id"], "zone:gazebo");
        assert_eq!(preview["changedObjects"][0]["kind"], "sceneObject");
        assert_eq!(preview["changedObjects"][0]["action"], "added");
        assert_eq!(preview["diagnostics"], json!([]));
        commit_preview_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", &project_id, preview["previewId"].as_str().unwrap(), 0, "describe-anchor").unwrap();
        let described = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.describe", &json!({"projectId":project_id})).unwrap();
        assert_eq!(described["objectCounts"]["anchor"], 1);
        assert_eq!(described["revision"], 1);
        assert_eq!(described["editableCategories"][0], "game");
        assert_eq!(described["cityLayout"]["seed"], 7);
        // 紧凑摘要不含完整文档：场景对象数组与规则 JSON 不得出现
        assert!(described.get("scene").is_none());
        assert!(described.get("game").is_none());
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.describe",
            &json!({"projectId":project_id,"revision":0})).unwrap_err(), "revision_conflict");
        let selected = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.describe",
            &json!({"projectId":project_id,"selectedObjectId":"zone:gazebo"})).unwrap();
        assert_eq!(selected["selected"]["id"], "zone:gazebo");
        assert!(selected["selected"]["transform"].is_object());
        let capabilities = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.capabilities.list", &json!({})).unwrap();
        assert_eq!(capabilities["schemaVersion"], 1);
        assert_eq!(capabilities["categories"]["scene"]["objectKinds"][0], "model");
        assert_eq!(capabilities["preview"]["singleUse"], true);
        // structure_check：诊断项结构（code/severity/source/objectId）与未运行项如实标注
        let validated = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.structure_check", &json!({"projectId":project_id})).unwrap();
        assert_eq!(validated["ok"], true);
        for entry in validated["items"].as_array().unwrap() {
            assert!(entry.get("code").is_some() && entry.get("severity").is_some() && entry.get("source").is_some(),
                "validation item must carry code/severity/source: {entry}");
        }
        for entry in validated["unchecked"].as_array().unwrap() {
            assert!(entry.get("check").is_some() && entry.get("reason").is_some(), "unchecked entry must name the check: {entry}");
        }
        let filtered = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.capabilities.list", &json!({"category":"scene"})).unwrap();
        assert_eq!(filtered["category"], "scene");
        assert!(filtered["capabilities"].get("preview").is_some());
        assert!(filtered["supportedCategories"].as_array().unwrap().iter().any(|value| value == "game"));
        // 游戏预览同样带结构化差异
        let project = read_project(&home, &project_id).unwrap();
        let game_preview = preview_replace_game(&home, "studio-instance", &project_id, 1, &project["game"]).unwrap();
        assert_eq!(game_preview["changedObjects"][0]["kind"], "game");
        assert_eq!(game_preview["diagnostics"], json!([]));
        let _ = std::fs::remove_dir_all(home);
    }

    // ── 车辆定义（2026-11-15 泛化切片）──

    /// 与 Studio 适配器同构的完整 VehicleProfileV1 载荷；camera 用生成目录默认公式
    /// （maxHalf = 5.0 → followDistance 32.5 / heightOffset 13.0 / fov 55）。
    fn flight_vehicle_payload(id: &str) -> Value {
        json!({"schemaVersion":1,"id":id,"label":"试验扑翼机","modelAssetId":null,"flightModel":"flapping",
            "physics":{"massKg":420,"wingAreaM2":20,"thrustN":11000,"maxSpeedMps":110,"dragCoefficient":0.09,
                "turnRateRps":0.8,"climbRateMps":30,"sinkRateMps":24,"flapFrequencyHz":2.2,"flapAmplitudeRad":1.0},
            "bounds":{"halfLengthM":3.8,"halfWidthM":5.0,"halfHeightM":1.5},
            "camera":{"followDistanceM":32.5,"heightOffsetM":13.0,"fovDeg":55.0}})
    }

    fn vehicle_envelope(ok: bool, project_id: &str, base_revision: u64, vehicle: &Value) -> Value {
        game_envelope(ok, project_id, base_revision, vehicle)
    }

    #[test]
    fn vehicle_define_is_envelope_gated_cas_bound_and_idempotent() {
        let home = home();
        publish_city_layout_snapshot(&home, &layout_snapshot()).unwrap();
        let created = create_project_from_city_layout(&home, LOCAL_CREATOR_OWNER, "flight-checkpoint", "create-vehicle", "world-rev-test").unwrap();
        let project_id = created["projectId"].as_str().unwrap().to_owned();
        let vehicle = flight_vehicle_payload("vehicle.flap-test");
        let invoke = |payload: &Value| dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.vehicle.define", payload);
        // 缺信封（legacy 直通已关闭）
        let mut request = json!({"projectId":project_id,"baseRevision":0,"vehicleId":"vehicle.flap-test","vehicle":vehicle,"operationId":"define-vehicle-1"});
        assert_eq!(invoke(&request).unwrap_err(), "creator_validation_required");
        // 摘要不匹配（不同载荷）
        let mut envelope = vehicle_envelope(true, &project_id, 0, &vehicle);
        envelope["payloadDigest"] = json!(format!("sha256:{}", "1".repeat(64)));
        assert_eq!(invoke(&request.clone().as_object_mut().map(|object| { object.insert("validation".into(), envelope); json!(object) }).unwrap()).unwrap_err(), "creator_validation_scope_mismatch");
        // 判负信封
        let rejected = vehicle_envelope(false, &project_id, 0, &vehicle);
        let mut request_bad = request.clone();
        request_bad["validation"] = rejected;
        assert_eq!(invoke(&request_bad).unwrap_err(), "creator_preview_invalid");
        // 好信封：提交成功、revision 前进
        request["validation"] = vehicle_envelope(true, &project_id, 0, &vehicle);
        let defined = invoke(&request).unwrap();
        assert_eq!(defined["revision"], 1);
        assert_eq!(defined["vehicleId"], "vehicle.flap-test");
        assert_eq!(defined["action"], "added");
        // 幂等：同一 operationId + 同一载荷返回原结果，不产生新 revision
        assert_eq!(invoke(&request).unwrap(), defined);
        assert_eq!(read_project(&home, &project_id).unwrap()["revision"], 1);
        // 不同载荷复用同一 operationId → operation_id_conflict
        let mut changed = flight_vehicle_payload("vehicle.flap-test");
        changed["physics"]["massKg"] = json!(430);
        let mut conflict = request.clone();
        conflict["baseRevision"] = json!(1);
        conflict["vehicle"] = changed.clone();
        conflict["validation"] = vehicle_envelope(true, &project_id, 1, &changed);
        assert_eq!(invoke(&conflict).unwrap_err(), "operation_id_conflict");
        // CAS：baseRevision 漂移拒绝
        let mut stale = request.clone();
        stale["baseRevision"] = json!(0);
        stale["operationId"] = json!("define-vehicle-stale");
        stale["validation"] = vehicle_envelope(true, &project_id, 0, &vehicle);
        assert_eq!(invoke(&stale).unwrap_err(), "revision_conflict");
        // vehicleId 与 profile.id 不一致拒绝
        let mut mismatch = request.clone();
        mismatch["vehicleId"] = json!("vehicle.other");
        mismatch["operationId"] = json!("define-vehicle-mismatch");
        assert_eq!(invoke(&mismatch).unwrap_err(), "creator_vehicle_invalid");
        // upsert：同 id 再定义 → updated，revision 再前进
        let mut update = request.clone();
        update["baseRevision"] = json!(1);
        update["operationId"] = json!("define-vehicle-2");
        update["validation"] = vehicle_envelope(true, &project_id, 1, &vehicle);
        let updated = invoke(&update).unwrap();
        assert_eq!(updated["action"], "updated");
        assert_eq!(updated["revision"], 2);
        // 检视：白名单字段 + 绑定挂载列表（此时为空）；revision 漂移拒绝
        let inspected = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.vehicle.inspect",
            &json!({"projectId":project_id,"vehicleId":"vehicle.flap-test","revision":2})).unwrap();
        assert_eq!(inspected["vehicle"]["flightModel"], "flapping");
        assert_eq!(inspected["boundMounts"], json!([]));
        // 边界：宿主只回事实（profile + 绑定），不做飞行性能推导——那是 city-sdk 的
        // estimateVehiclePerformanceV1（Creator 预览 / Agent 自行投影）。宿主那份推导
        // 曾与引擎各写一遍（maxSpeed/1.8 vs Math.max(6, …)），已整条移除。
        assert!(inspected.get("estimatedPerformance").is_none(), "inspect must report facts, not a derivation");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.vehicle.inspect",
            &json!({"projectId":project_id,"vehicleId":"vehicle.flap-test","revision":1})).unwrap_err(), "revision_conflict");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.vehicle.inspect",
            &json!({"projectId":project_id,"vehicleId":"vehicle.missing"})).unwrap_err(), "creator_vehicle_not_found");
        let _ = std::fs::remove_dir_all(home);
    }

    #[test]
    fn vehicle_structural_checks_reject_invalid_profiles_before_the_semantic_gate() {
        let home = home();
        publish_city_layout_snapshot(&home, &layout_snapshot()).unwrap();
        let created = create_project_from_city_layout(&home, LOCAL_CREATOR_OWNER, "flight-checkpoint", "create-vehicle-struct", "world-rev-test").unwrap();
        let project_id = created["projectId"].as_str().unwrap().to_owned();
        let attempt = |vehicle: Value, operation_id: &str| {
            let envelope = vehicle_envelope(true, &project_id, 0, &vehicle);
            dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.vehicle.define",
                &json!({"projectId":project_id,"baseRevision":0,"vehicleId":vehicle["id"],"vehicle":vehicle,"operationId":operation_id,"validation":envelope}))
        };
        // 物理键集合必须与声明的气动模型完全一致（exact-keys）
        let mut missing_flap = flight_vehicle_payload("vehicle.bad-keys");
        missing_flap["physics"].as_object_mut().unwrap().remove("flapFrequencyHz");
        assert_eq!(attempt(missing_flap, "define-bad-keys").unwrap_err(), "creator_vehicle_invalid");
        // 数值越界
        let mut fast = flight_vehicle_payload("vehicle.fast");
        fast["physics"]["maxSpeedMps"] = json!(200);
        assert_eq!(attempt(fast, "define-fast").unwrap_err(), "creator_vehicle_out_of_bounds");
        // 跨字段物理比值（翼载荷/推重比）
        let mut heavy = flight_vehicle_payload("vehicle.heavy");
        heavy["physics"]["wingAreaM2"] = json!(2.0);
        assert_eq!(attempt(heavy, "define-heavy").unwrap_err(), "creator_vehicle_unphysical");
        // modelAssetId 必须引用项目资产
        let mut with_asset = flight_vehicle_payload("vehicle.asset");
        with_asset["modelAssetId"] = json!("model-absent");
        assert_eq!(attempt(with_asset, "define-asset").unwrap_err(), "creator_vehicle_asset_not_found");
        // 相机字段不齐同样拒绝
        let mut camera = flight_vehicle_payload("vehicle.camera");
        camera["camera"].as_object_mut().unwrap().remove("fovDeg");
        assert_eq!(attempt(camera, "define-camera").unwrap_err(), "creator_vehicle_invalid");
        // 预算：16 个 vehicle 之后拒绝第 17 个
        for index in 0..MAX_PROJECT_VEHICLES {
            let vehicle = flight_vehicle_payload(&format!("vehicle.bulk-{index}"));
            let envelope = vehicle_envelope(true, &project_id, index as u64, &vehicle);
            dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.vehicle.define",
                &json!({"projectId":project_id,"baseRevision":index,"vehicleId":vehicle["id"],"vehicle":vehicle,"operationId":format!("define-bulk-{index}"),"validation":envelope})).unwrap();
        }
        let overflow = flight_vehicle_payload("vehicle.overflow");
        let envelope = vehicle_envelope(true, &project_id, MAX_PROJECT_VEHICLES as u64, &overflow);
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.vehicle.define",
            &json!({"projectId":project_id,"baseRevision":MAX_PROJECT_VEHICLES as u64,"vehicleId":overflow["id"],"vehicle":overflow,"operationId":"define-overflow","validation":envelope})).unwrap_err(),
            "creator_vehicle_budget_exceeded");
        let _ = std::fs::remove_dir_all(home);
    }

    /// 车辆预览走既有 preview/commit 链：宿主签发 previewId + 结构核对结果，不推导性能
    /// （性能投影由 Studio 用 SDK 补齐，见 sdkValidation.estimateVehiclePerformanceV1）。
    #[test]
    fn vehicle_preview_issues_a_committable_preview_without_a_host_derivation() {
        let home = home();
        publish_city_layout_snapshot(&home, &layout_snapshot()).unwrap();
        let created = create_project_from_city_layout(&home, LOCAL_CREATOR_OWNER, "flight-checkpoint", "create-vehicle-preview", "world-rev-test").unwrap();
        let project_id = created["projectId"].as_str().unwrap().to_owned();
        let vehicle = flight_vehicle_payload("vehicle.preview-test");
        let preview = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.vehicle.preview",
            &json!({"projectId":project_id,"baseRevision":0,"vehicle":vehicle,"validation":vehicle_envelope(true, &project_id, 0, &vehicle)})).unwrap();
        assert_eq!(preview["vehicleId"], "vehicle.preview-test");
        assert_eq!(preview["validation"], "studio-envelope");
        assert!(preview.get("estimatedPerformance").is_none(), "preview must not fabricate a performance projection");
        assert_eq!(preview["diagnostics"], json!([]));
        let committed = commit_preview_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", &project_id,
            preview["previewId"].as_str().unwrap(), 0, "commit-vehicle-preview").unwrap();
        assert_eq!(committed["revision"], 1);
        let document = read_project(&home, &project_id).unwrap();
        assert_eq!(document["vehicles"].as_array().unwrap().len(), 1);
        // 预览一次性：重复提交同一 preview 被拒绝
        assert_eq!(commit_preview_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", &project_id,
            preview["previewId"].as_str().unwrap(), 1, "commit-vehicle-again").unwrap_err(), "preview_expired");
        let _ = std::fs::remove_dir_all(home);
    }


    // MCP P1（设计 §6.4）：inspect 白名单字段与三种来源（场景对象/挂载/只读布局锚点）、
    // validate 的静态检查与如实未运行项、capabilities 的类别过滤。
    #[test]
    fn scene_inspect_validate_and_capabilities_cover_whitelisted_views() {
        let home = home();
        publish_city_layout_snapshot(&home, &layout_snapshot()).unwrap();
        let created = create_project_from_city_layout(&home, LOCAL_CREATOR_OWNER, "checkpoint-race", "create-inspect", "world-rev-test").unwrap();
        let project_id = created["projectId"].as_str().unwrap().to_owned();
        let preview = preview_scene_operations(&home, "studio-instance", &project_id, 0, &json!([
            {"op":"anchor.upsert","object":{"id":"zone:gazebo","kind":"anchor","transform":{"positionMeters":{"x":1.0,"y":0.0,"z":2.0},"rotationRadians":{"x":0.0,"y":0.0,"z":0.0},"scale":{"x":1.0,"y":1.0,"z":1.0}},
                "anchor":{"id":"zone:gazebo","kind":"zone","capabilities":["walk"],"geometryRef":"layout-ground:gazebo"}}}
        ])).unwrap();
        commit_preview_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", &project_id, preview["previewId"].as_str().unwrap(), 0, "inspect-anchor").unwrap();
        let revision = read_project(&home, &project_id).unwrap()["revision"].as_u64().unwrap();
        // 场景对象：白名单字段 + 编辑通道
        let inspected = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.inspect",
            &json!({"projectId":project_id,"revision":revision,"objectId":"zone:gazebo"})).unwrap();
        assert_eq!(inspected["object"]["kind"], "anchor");
        assert_eq!(inspected["object"]["editableVia"][0], "scene.object.upsert");
        assert_eq!(inspected["source"], "scene");
        // 挂载：先绑一个再检查
        let game_digest = digest(&canonical_json(&read_project(&home, &project_id).unwrap()["game"]).unwrap());
        let mount = json!({"schemaVersion":1,"mountId":"inspect-mount",
            "layout":{"kind":"city-layout","id":"city-layout-v1-test","version":"1","digest":"world-rev-test"},
            "game":{"kind":"city-minigame","id":read_project(&home, &project_id).unwrap()["game"]["id"],"version":"1","digest":game_digest},
            "entryAnchorId":"road-spawn:a","bindings":{"points":["road-checkpoint:ab","road-checkpoint:bc","road-checkpoint:cd"]},"parameterOverrides":{"timeLimitTicks":2400}});
        let mount_preview = preview_scene_operations(&home, "studio-instance", &project_id, 1, &json!([{"op":"mount.bind","mount":mount}])).unwrap();
        commit_preview_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", &project_id, mount_preview["previewId"].as_str().unwrap(), 1, "inspect-mount").unwrap();
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.inspect",
            &json!({"projectId":project_id,"revision":2,"objectId":"inspect-mount"})).unwrap()["object"]["kind"], "mount");
        // 只读布局锚点：不可编辑
        let layout_anchor = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.inspect",
            &json!({"projectId":project_id,"revision":2,"objectId":"road-spawn:a"})).unwrap();
        assert_eq!(layout_anchor["source"], "cityLayout");
        assert_eq!(layout_anchor["object"]["editable"], false);
        // 未知名与 revision 漂移
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.inspect",
            &json!({"projectId":project_id,"revision":2,"objectId":"zone:missing"})).unwrap_err(), "creator_object_not_found");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.inspect",
            &json!({"projectId":project_id,"revision":99,"objectId":"zone:gazebo"})).unwrap_err(), "revision_conflict");
        // structure_check：干净项目 ok + 运行时检查如实未运行；validate 方法不再由 Rust 提供（§5.3）
        let validated = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.structure_check", &json!({"projectId":project_id})).unwrap();
        assert_eq!(validated["ok"], true);
        assert!(validated["unchecked"].as_array().unwrap().iter().any(|entry| entry["check"] == "drive_reachability"));
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.scene.validate",
            &json!({"projectId":project_id})).unwrap_err(), "creator_method_unavailable");
        // capabilities：类别过滤与未知类别
        let filtered = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.capabilities.list", &json!({"category":"scene"})).unwrap();
        assert_eq!(filtered["category"], "scene");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.capabilities.list",
            &json!({"category":"physics-sim"})).unwrap_err(), "creator_capability_unknown");
        let _ = std::fs::remove_dir_all(home);
    }

    #[test]
    fn playtest_handoff_is_release_pinned_city_bound_and_returns_once() {
        let home = home();
        let (project_id, revision) = publishable_project(&home);
        seed_host_verified_candidate(&home, &project_id, revision);
        let published = publish_project_release(&home, &project_id, revision).unwrap();
        let release_id = published["releaseId"].as_str().unwrap();
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.return_context", &json!({})).unwrap(), Value::Null);
        let start = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start", &json!({"releaseId":release_id})).unwrap();
        assert_eq!(start["status"], "pending");
        let run_id = start["runId"].as_str().unwrap().to_owned();
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start", &json!({"releaseId":release_id})).unwrap(), start);
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start", &json!({"releaseId":release_id,"projectId":"other-project"})).unwrap_err(), "creator_release_project_mismatch");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start", &json!({"releaseId":release_id,"expectedRevision":revision + 1})).unwrap_err(), "creator_release_revision_mismatch");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start", &json!({"releaseId":release_id,"projectId":null})).unwrap_err(), "creator_request_invalid");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance", "creator.project.playtest.start", &json!({"releaseId":release_id,"expectedRevision":"1"})).unwrap_err(), "creator_request_invalid");
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-instance-2", "creator.project.playtest.start", &json!({"releaseId":release_id})).unwrap_err(), "creator_playtest_active");

        let claimed = dispatch_city_runtime(&home, "city-instance", "city.creator.playtest.claim", &json!({})).unwrap();
        assert_eq!(claimed["runId"], run_id);
        assert_eq!(claimed["releaseId"], release_id);
        assert_eq!(claimed["projectId"], project_id);
        assert_eq!(claimed["revision"], revision);
        assert_eq!(claimed["skinId"], "miami-vice");
        assert_eq!(claimed["game"]["id"], "creator.checkpoint-race");
        assert_eq!(claimed["mounts"][0]["mountId"], "release-mount");
        let snapshot_digest = claimed["snapshotDigest"].as_str().unwrap().to_owned();
        assert_eq!(snapshot_digest.len(), 71);
        assert_eq!(claimed["returnContext"], json!({"projectId":project_id,"revision":revision}));
        let game_ref = claimed["mounts"][0]["game"].clone();
        let evidence = json!({"schemaVersion":1,"runtimeVersion":"city-mini-game-runtime-v1","releaseId":release_id,
            "projectRevision":revision,"snapshotDigest":snapshot_digest,"worldRevision":"world-rev-test","seed":7,"game":{"id":game_ref["id"],"version":game_ref["version"],"digest":game_ref["digest"]},
            "tick":812,"counters":{"next":3},"outcome":"success","reasonCode":null});
        assert_eq!(dispatch_city_runtime(&home, "another-city", "city.creator.playtest.claim", &json!({})).unwrap_err(), "creator_playtest_claimed");
        assert_eq!(dispatch_city_runtime(&home, "another-city", "city.creator.playtest.finish", &json!({"runId":run_id,"status":"completed","evidence":evidence})).unwrap_err(), "creator_playtest_instance_mismatch");

        let mut mismatched = evidence.clone(); mismatched["worldRevision"] = json!("world-rev-other");
        assert_eq!(dispatch_city_runtime(&home, "city-instance", "city.creator.playtest.finish", &json!({"runId":run_id,"status":"completed","evidence":mismatched})).unwrap_err(), "creator_playtest_evidence_invalid");
        let mut wrong_outcome = evidence.clone(); wrong_outcome["outcome"] = json!("failure");
        assert_eq!(dispatch_city_runtime(&home, "city-instance", "city.creator.playtest.finish", &json!({"runId":run_id,"status":"completed","evidence":wrong_outcome})).unwrap_err(), "creator_playtest_evidence_mismatch");
        assert_eq!(dispatch_city_runtime(&home, "city-instance", "city.creator.playtest.finish", &json!({"runId":run_id,"status":"completed","evidence":null})).unwrap_err(), "creator_playtest_evidence_required");
        let finished = dispatch_city_runtime(&home, "city-instance", "city.creator.playtest.finish", &json!({"runId":run_id,"status":"completed","evidence":evidence})).unwrap();
        assert_eq!(finished["status"], "completed");
        assert_eq!(dispatch_city_runtime(&home, "city-instance", "city.creator.playtest.finish", &json!({"runId":run_id,"status":"completed","evidence":evidence})).unwrap(), finished);
        assert_eq!(dispatch_city_runtime(&home, "city-instance", "city.creator.playtest.finish", &json!({"runId":run_id,"status":"failed","evidence":null})).unwrap_err(), "creator_playtest_terminal");
        let returned = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-resumed", "creator.project.playtest.return_context", &json!({})).unwrap();
        assert_eq!(returned, json!({"runId":run_id,"projectId":project_id,"revision":revision,"status":"completed","evidence":evidence,"failureCode":null}));
        assert_eq!(dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-resumed", "creator.project.playtest.return_context", &json!({})).unwrap(), Value::Null);
        let history = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-resumed", "creator.project.playtest.history", &json!({"projectId":project_id,"limit":8})).unwrap();
        // PR07：直接发布的强闸种子候选也在同一项目下，历史共两条；种子恒排最旧。
        assert_eq!(history["runs"].as_array().unwrap().len(), 2);
        assert_eq!(history["runs"][0]["evidenceSource"], "city-client-reported");
        assert_eq!(history["runs"][0]["evidence"], evidence);
        assert_eq!(history["runs"][1]["evidenceSource"], "host-verified");
        let retry = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-retry", "creator.project.playtest.start", &json!({"releaseId":release_id})).unwrap();
        let retry_id = retry["runId"].as_str().unwrap();
        dispatch_city_runtime(&home, "city-retry", "city.creator.playtest.claim", &json!({})).unwrap();
        assert_eq!(dispatch_city_runtime(&home, "city-retry", "city.creator.playtest.finish", &json!({
            "runId":retry_id,"status":"failed","evidence":null,"failureCode":"creator_entry_spawn_unavailable"
        })).unwrap()["failureCode"], "creator_entry_spawn_unavailable");
        let failed = dispatch_as(&home, LOCAL_CREATOR_OWNER, "studio-retry-resumed", "creator.project.playtest.return_context", &json!({})).unwrap();
        assert_eq!(failed["failureCode"], "creator_entry_spawn_unavailable");
        assert_eq!(dispatch_city_runtime(&home, "city-retry", "city.creator.playtest.finish", &json!({
            "runId":retry_id,"status":"failed","evidence":null,"failureCode":"has spaces"
        })).unwrap_err(), "creator_request_invalid");
        let _ = std::fs::remove_dir_all(home);
    }

    #[test]
    fn project_preview_commit_revision_and_idempotency() {
        let home = home();
        let created = create_project(&home, "instance-test", "checkpoint-race", "create-1").unwrap();
        assert_eq!(create_project(&home, "instance-test", "checkpoint-race", "create-1").unwrap(), created);
        assert_eq!(create_project(&home, "instance-test", "collect-one", "create-1").unwrap_err(), "operation_id_conflict");
        let project = created["projectId"].as_str().unwrap();
        assert_eq!(operation_status(&home, "instance-test", project, "missing").unwrap()["status"], "not_found");
        let mut game = read_project(&home, project).unwrap()["game"].clone();
        game["rules"]["counters"]["next"]["max"] = json!(4);
        let preview = preview_replace_game(&home, "instance-test", project, 0, &game).unwrap();
        let preview_id = preview["previewId"].as_str().unwrap();
        assert_eq!(commit_preview(&home, "other-instance", project, preview_id, 0, "edit-1").unwrap_err(), "permission_denied");
        let committed = commit_preview(&home, "instance-test", project, preview_id, 0, "edit-1").unwrap();
        assert_eq!(committed["revision"], 1);
        assert_eq!(read_project(&home, project).unwrap()["revision"], 1);
        assert_eq!(operation_status(&home, "instance-test", project, "edit-1").unwrap()["status"], "committed");
        assert_eq!(commit_preview(&home, "instance-test", project, preview_id, 0, "edit-1").unwrap(), committed);
        assert_eq!(commit_preview(&home, "instance-test", project, preview_id, 0, "edit-other").unwrap_err(), "preview_expired");
        // 语义搬运后（§7 P2）：结构侧只拒绝形状/预算违例；host.call 之类语义违例
        // 由 city-sdk 判定并经 validation 信封拒绝（见 P2-1 闸门测试）。
        let bad_game = json!({"schemaVersion":1,"id":"x","rulesVersion":1,"slots":{},"rules":{"counters":{},"nodes":[]},"script":"bad"});
        assert_eq!(structural_game_check(&bad_game).unwrap_err(), "creator_game_invalid");
        let structurally_fine = json!({"schemaVersion":1,"id":"x","rulesVersion":1,"slots":{},"rules":{"counters":{},"nodes":[]}});
        assert!(structural_game_check(&structurally_fine).is_ok());
        let _ = std::fs::remove_dir_all(home);
    }

